TYPE ST_Recipe :
STRUCT
    recipeID : INT;
    ingredientType : INT;
    ingredientRatio : REAL;
    productionTemperature : REAL;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_P17
VAR_INPUT
    addRecipe : BOOL;
    deleteRecipe : BOOL;
    modifyRecipe : BOOL;
    queryRecipe : BOOL;
    recipeIn : ST_Recipe;
    recipeID : INT;
    ingredientType : INT;
    ingredientRatio : REAL;
    productionTemperature : REAL;
END_VAR
VAR_OUTPUT
    recipeAdded : BOOL := FALSE;
    recipeDeleted : BOOL := FALSE;
    recipeModified : BOOL := FALSE;
    recipeQueryResult : ST_Recipe;
    error : BOOL := FALSE;
    status : WORD := WORD#16#0000;
END_VAR
VAR_IN_OUT
    recipe : ARRAY[1..10] OF ST_Recipe;
END_VAR
VAR
    initialized : BOOL := FALSE;
    previousAdd : BOOL := FALSE;
    previousDelete : BOOL := FALSE;
    previousModify : BOOL := FALSE;
    previousQuery : BOOL := FALSE;
    addEdge : BOOL;
    deleteEdge : BOOL;
    modifyEdge : BOOL;
    queryEdge : BOOL;
    i : INT;
    foundIndex : INT;
    emptyIndex : INT;
    duplicateID : BOOL;
END_VAR

(*
    每次调用为一个20 ms扫描周期。

    需求冲突及未明确事项：
    1. 完整I/O表包含四个标量输入，骨架未列出。
       此处保留完整I/O表接口；按需求原文，以recipeIn作为操作数据，
       不写入标量输入，也不将其暗中覆盖到recipeIn。

    2. K1“写入时只能落到空位”若适用于全部写操作，
       与“修改已有配方”冲突。此处新增只使用空位；
       修改遵循原文，替换已有非空记录。
       因此不能声称同时满足K1的字面全称解释和修改要求。

    3. 同时请求的仲裁顺序未规定。此实现采用
       addRecipe > deleteRecipe > modifyRecipe > queryRecipe，
       每扫描只执行一个操作；同拍未选中的边沿不排队。
       此顺序是实现选择，不是题面已规定的安全优先级。

    4. 请求采用上升沿触发。成功标志为单扫描脉冲；
       error/status保持到下一次实际执行的请求。
       查询结果保持到下一次成功查询。

    5. 编号0是空位，不作为可查询、删除或修改的已有配方。
       新增仍按原文与全部槽位比较编号：
       新增0在有空位时为重复编号8002，满库时为8003，
       因而不会报告成功或写入编号0。
       原文未单独定义“非法编号”的错误码。

    6. 首次调用只建立指定初态，不执行请求，以满足C10。
       初次调用期间为TRUE且随后保持TRUE的请求，
       可在第二次调用执行一次。

    未声称经过编译或逐周期功能验证。
*)

recipeAdded := FALSE;
recipeDeleted := FALSE;
recipeModified := FALSE;

IF NOT initialized THEN
    FOR i := 1 TO 10 DO
        recipe[i].recipeID := 0;
    END_FOR;

    recipeQueryResult.recipeID := 0;
    recipeQueryResult.ingredientType := 0;
    recipeQueryResult.ingredientRatio := 0.0;
    recipeQueryResult.productionTemperature := 0.0;

    error := FALSE;
    status := WORD#16#0000;

    previousAdd := FALSE;
    previousDelete := FALSE;
    previousModify := FALSE;
    previousQuery := FALSE;
    initialized := TRUE;
ELSE
    addEdge := addRecipe AND NOT previousAdd;
    deleteEdge := deleteRecipe AND NOT previousDelete;
    modifyEdge := modifyRecipe AND NOT previousModify;
    queryEdge := queryRecipe AND NOT previousQuery;

    IF addEdge OR deleteEdge OR modifyEdge OR queryEdge THEN
        error := FALSE;
        status := WORD#16#0000;

        foundIndex := 0;
        emptyIndex := 0;
        duplicateID := FALSE;

        FOR i := 1 TO 10 DO
            IF recipe[i].recipeID = 0 THEN
                IF emptyIndex = 0 THEN
                    emptyIndex := i;
                END_IF;
            END_IF;

            IF recipe[i].recipeID = recipeIn.recipeID THEN
                duplicateID := TRUE;

                IF (recipe[i].recipeID <> 0) AND
                   (foundIndex = 0) THEN
                    foundIndex := i;
                END_IF;
            END_IF;
        END_FOR;

        IF addEdge THEN
            IF duplicateID THEN
                error := TRUE;
                status := WORD#16#8002;
            ELSIF emptyIndex = 0 THEN
                error := TRUE;
                status := WORD#16#8003;
            ELSE
                recipe[emptyIndex] := recipeIn;
                recipeAdded := TRUE;
            END_IF;

        ELSIF deleteEdge THEN
            IF foundIndex = 0 THEN
                error := TRUE;
                status := WORD#16#8004;
            ELSE
                recipe[foundIndex].recipeID := 0;
                recipeDeleted := TRUE;
            END_IF;

        ELSIF modifyEdge THEN
            IF foundIndex = 0 THEN
                error := TRUE;
                status := WORD#16#8005;
            ELSE
                recipe[foundIndex] := recipeIn;
                recipeModified := TRUE;
            END_IF;

        ELSIF queryEdge THEN
            IF foundIndex = 0 THEN
                error := TRUE;
                status := WORD#16#8001;
            ELSE
                recipeQueryResult := recipe[foundIndex];
            END_IF;
        END_IF;
    END_IF;

    previousAdd := addRecipe;
    previousDelete := deleteRecipe;
    previousModify := modifyRecipe;
    previousQuery := queryRecipe;
END_IF;

END_FUNCTION_BLOCK
